mapper.insert:
INSERT INTO attendance_record (
    employee_id, work_date, check_in_time, status, tardy_reason, is_closed
) VALUES (
            #{employeeId}, #{workDate}, #{checkInTime}, #{status}, #{tardyReason}, FALSE
        )

mapper.update:
UPDATE attendance_record
SET check_out_time = #{checkOutTime},
    status = #{status}
WHERE employee_id = #{employeeId}
  AND work_date = #{workDate}
  AND check_out_time IS NULL
  AND COALESCE(is_closed, FALSE) = FALSE

mapper.select:
SELECT attendance_id as attendanceId, employee_id as employeeId, work_date as workDate, check_in_time as checkInTime, check_out_time as checkOutTime, status as status, tardy_reason as tardyReason, modify_reason as modifyReason, is_closed as closed, overtime_hours as overtimeHours, night_work_hours as nightWorkHours, holiday_work_hours as holidayWorkHours, is_unpaid_leave as unpaidLeave FROM attendance_record WHERE employee_id = #{employeeId} AND
AND status = #{status}
ORDER BY work_date DESC

mapper.update:
UPDATE attendance_record
SET overtime_hours = #{overtimeHours},
    modify_reason = CASE
        WHEN modify_reason IS NULL OR modify_reason = '' THEN #{modifyReason}
        ELSE CONCAT(modify_reason, ' | ', #{modifyReason})
    END
WHERE employee_id = #{employeeId}
  AND work_date = #{workDate}
  AND COALESCE(is_closed, FALSE) = FALSE
